-radius:6px;padding:5px 8px}\n.req b{color:var(--ink)}\n\n.tabs{display:flex;gap:2px;flex:1;min-width:0}\n.tab{flex:1;min-width:0;min-height:28px;border:0;border-bottom:2px solid transparent;background:none;color:var(--muted);font:inherit;font-size:12px;cursor:pointer;padding:0 2px}\n.tab.on{color:var(--ink);border-bottom-color:var(--accent);font-weight:700}\n.row{display:flex;align-items:center;gap:6px;min-width:0;padding:3px 0;border-bottom:1px solid var(--line);flex:none}\n.row.addrow{border-bottom:0}\n.lab{display:flex;align-items:center;gap:6px;flex:1;min-width:0;cursor:pointer}\n.lab input{flex:none;width:16px;height:16px;accent-color:var(--accent)}\n.nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.srow{display:flex;flex-direction:column;gap:3px;padding:5px 0;border-bottom:1px solid var(--line);flex:none}\n.sb{display:flex;gap:5px;flex-wrap:wrap}\n.hbtn{flex:1;min-width:0;display:flex;align-items:center;gap:6px;min-height:32px;padding:0 4px;border:0;background:none;color:var(--ink);font:inherit;font-size:13px;cursor:pointer;text-align:left}\n\n.seg{display:flex;gap:3px;height:6px;flex:none}\n.seg i{flex:1;border-radius:3px;background:var(--line)}\n.seg i.done{background:var(--accent)}\n.seg i.skipped{background:var(--muted);opacity:.5}\n.seg i.doing{background:var(--accent-alt)}\n.rbody{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}\n.pane{gap:6px}\n.stp{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px;flex:none}\n.si{display:flex;align-items:center;gap:6px;min-width:0}\n.sdot{flex:none;width:26px;height:26px;padding:0;border-radius:50%;border:1.5px solid var(--line);background:var(--panel-paper);color:var(--muted);font:inherit;font-size:12px;cursor:pointer}\n.si.done .sdot{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}\n.si.skipped .sdot{border-style:dashed}\n.si.cur .sdot{border:2px solid var(--accent);color:var(--ink);box-shadow:0 0 0 2px var(--soft);font-