const PRESETS=[['week','本周'],['last','上周'],['7d','近7天'],['custom','自定义']];
const KINDS=[['calendar','日历'],['mail','邮件'],['digest','项目进展与问题'],['write','撰写周报'],['manual','手动记录']];
const STAT={todo:'待做',doing:'进行中',done:'已完成',skipped:'已跳过'};
const PHASE={steps:'进行中',review:'待审阅',done:'已审阅',cancelled:'已放弃'};
function kindLabel(k){for(let i=0;i<KINDS.length;i++){if(KINDS[i][0]===k)return KINDS[i][1];}return k;}

function initialize(s){
  if(s&&s.cfg&&Array.isArray(s.runs))return s;
  const b=s&&typeof s==='object'?s:{};
  return Object.assign({},b,{
    cfg:b.cfg||{preset:'week',start:'',end:'',projects:[],reportReq:'',steps:[
      {id:'st-calendar',title:'看日历',req:'',kind:'calendar',on:true},
      {id:'st-mail',title:'看邮件',req:'',kind:'mail',on:true},
      {id:'st-digest',title:'整理项目进展和问题',req:'',kind:'digest',on:true},
      {id:'st-write',title:'写周报',req:'',kind:'write',on:true}
    ]},
    runs:Array.isArray(b.runs)?b.runs:[]
  });
}
function norm(s){
  const b=s&&typeof s==='object'?s:{};
  const c=Object.assign({preset:'week',start:'',end:'',projects:[],reportReq:'',steps:[]},b.cfg||{});
  return Object.assign({},b,{cfg:c,runs:Array.isArray(b.runs)?b.runs:[]});
}

function pd(str){const a=String(str||'').split('-');return new Date(+a[0],(+a[1])-1,+a[2]);}
function fd(d){const m=d.getMonth()+1,x=d.getDate();return d.getFullYear()+'-'+(m<10?'0':'')+m+'-'+(x<10?'0':'')+x;}
function addDays(str,n){const d=pd(str);d.setDate(d.getDate()+n);return fd(d);}
function weekStart(str){const d=pd(str);return addDays(str,-((d.getDay()+6)%7));}
function rangeOf(cfg,today){
  const p=cfg.preset;
  if(p==='last'){const s=addDays(weekStart(today),-7);return {start:s,end:addDays(s,6)};}
  if(p==='7d')return {start:addDays(today,-6),end:today};
  if(p==='custom')return {start:cfg.start||'',end:cfg.end||''};
  const s=weekStart(today);
  return {start:s,end:addDays(s,6)};
}
function md(str){const a=String(str||'').split('-');return a.length===3?(+a[1])+'/'+(+a[2]):'?';}
function rangeText(r){return md(r.start)+' – '+md(r.end);}
function rangeOk(r){
  const re=/^\d{4}-\d{2}-\d{2}$/;
  return re.test(r.start||'')&&re.test(r.end||'')&&r.start<=r.end;
}
function fmtTime(ms){
  const d=new Date(ms);
  const p=n=>(n<10?'0':'')+n;
  return p(d.getMonth()+1)+'/'+p(d.getDate())+' '+p(d.getHours())+':'+p(d.getMinutes());
}
function cn(n){return '一二三四五六七八九十'.charAt(n-1)||String(n);}

function stepHasContent(r,i){
  const st=r.steps[i];
  if(!st)return false;
  if(st.kind==='digest'&&r.projects.length){
    return r.projects.some(p=>{const v=(r.pn&&r.pn[p.id])||{};return !!((v.p||'').trim()||(v.i||'').trim());});
  }
  if(st.kind==='write')return !!(r.draft&&r.draft.trim());
  return !!(st.note&&st.note.trim());
}
function flushRun(r,d){
  const steps=r.steps.map((x,i)=>(i===r.idx&&d.note!==undefined)?Object.assign({},x,{note:d.note}):x);
  const pn=Object.assign({},r.pn||{});
  r.projects.forEach(p=>{
    const a='p:'+p.id,b='i:'+p.id;
    if(d[a]!==undefined||d[b]!==undefined){
      const o=Object.assign({},pn[p.id]);
      if(d[a]!==undefined)o.p=d[a];
      if(d[b]!==undefined)o.i=d[b];
      pn[p.id]=o;
    }
  });
  return Object.assign({},r,{steps:steps,pn:pn,draft:d.draft!==undefined?d.draft:(r.draft||'')});
}
function assemble(run){
  const L=['周报  '+run.start+' ~ '+run.end];
  let n=0;
  run.steps.forEach(st=>{
    if(st.kind==='write')return;
    n++;
    L.push('');
    L.push(cn(n)+'、'+st.title);
    if(st.kind==='digest'&&run.projects.length){
      run.projects.forEach(p=>{
        const v=(run.pn&&run.pn[p.id])||{};
        L.push('【'+p.name+'】');
        L.push('进展：'+((v.p||'').trim()||'（未填写）'));
        L.push('问题：'+((v.i||'').trim()||'（未填写）'));
      });
    }else{
      L.push((st.note||'').trim()||'（未记录）');
    }
  });
  return L.join('\n');
}
function advance(r,target,d){
  const x=flushRun(r,d);
  const from=x.idx;
  const has=stepHasContent(x,from);
  const steps=x.steps.map((s,i)=>i===from?Object.assign({},s,{status:has?'done':(target>from?'skipped':'todo')}):s);
  if(target>=steps.length){
    const y=Object.assign({},x,{steps:steps});
    return Object.assign({},y,{phase:'review',draft:(y.draft&&y.draft.trim())?y.draft:assemble(y)});
  }
  const t=Math.max(0,target);
  const s2=steps.map((s,i)=>i===t?Object.assign({},s,{status:'doing'}):(s.status==='doing'?Object.assign({},s,{status:'todo'}):s));
  return Object.assign({},x,{steps:s2,idx:t});
}

function txt(v){
  if(typeof v==='string')return v;
  if(v&&typeof v==='object')return String(v.name||v.address||v.email||'');
  return '';
}
function mailRows(data){
  let arr=Array.isArray(data)?data:null;
  if(!arr&&data&&typeof data==='object'){
    const ks=['messages','items','list','results','data','mails'];
    for(let i=0;i<ks.length&&!arr;i++){if(Array.isArray(data[ks[i]]))arr=data[ks[i]];}
  }
  if(!arr)return null;
  return arr.map(m=>{
    const o=m&&typeof m==='object'?m:{};
    return {
      date:txt(o.date||o.received_at||o.receivedAt||o.time||o.sent_at).slice(0,10),
      from:txt(o.from||o.sender||o.from_name),
      subject:txt(o.subject||o.title)||'（无主题）'
    };
  });
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,percent,size,host}=ctx;
  const S=norm(state);
  const cfg=S.cfg;
  const view=ui.view||'home';
  if(!ui.d)ui.d={};
  const rng=rangeOf(cfg,day());
  const act=S.runs.find(r=>r.phase==='steps'||r.phase==='review');
  const big=size==='3x6'||size==='6x6';

  const h=(tag,attrs,...c)=>{
    const k=[];
    c.forEach(a=>{(Array.isArray(a)?a:[a]).forEach(x=>{if(x!=null&&x!==false)k.push(x);});});
    return el(tag,attrs||{},...k);
  };
  const btn=(label,fn,cls,dis,aria)=>{
    const a={type:'button',class:'b '+(cls||''),onclick:fn};
    if(dis)a.disabled=true;
    if(aria)a['aria-label']=aria;
    return h('button',a,label);
  };
  const fail=e=>{ui.err='保存失败：'+((e&&e.message)||String(e));redraw();};
  const nav=(v,extra)=>{ui.view=v;ui.err='';ui.cf=null;ui.d={};if(extra)Object.assign(ui,extra);redraw();};
  const dvv=(k,saved)=>ui.d[k]!==undefined?ui.d[k]:saved;
  const errBar=()=>ui.err?h('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;
  const saveCfg=fn=>update(s=>{const n=norm(s);return Object.assign({},n,{cfg:fn(n.cfg)});}).catch(fail);
  function cfBtn(key,label,okLabel,fn,cls){
    const on=ui.cf===key;
    return btn(on?okLabel:label,()=>{if(on){ui.cf=null;fn();}else{ui.cf=key;redraw();}},(cls||'')+(on?' warn':''));
  }
  function job(key,fn){
    ui.jobs=ui.jobs||{};
    if(ui.jobs[key]&&ui.jobs[key].status==='loading')return;
    ui.jobs[key]={status:'loading'};
    redraw();
    Promise.resolve().then(fn).then(
      d=>{ui.jobs[key]={status:'ok',data:d};redraw();},
      e=>{ui.jobs[key]={status:'error',error:(e&&e.message)||String(e)};redraw();}
    );
  }
  function fetchMail(){
    return Promise.resolve(host.fetchData('connected.mail.message-list')).then(r=>{
      if(!r||r.status!=='ok'||r.data==null)throw new Error((r&&(r.errorCode||r.error||r.status))||'没有有效响应');
      return r.data;
    });
  }
  function mailErr(m){
    return /permission|denied|bind|绑定/i.test(m||'')?'邮箱尚未连接（permission_denied）：请先在平台连接邮箱后再试。':(m||'未知错误');
  }

  function rangeCtl(){
    const chips=h('div',{class:'chips'},PRESETS.map(p=>h('button',{type:'button',class:'chip'+(cfg.preset===p[0]?' on':''),'aria-pressed':String(cfg.preset===p[0]),onclick:()=>{ui.err='';saveCfg(c=>Object.assign({},c,{preset:p[0]}));}},p[1])));
    const dates=cfg.preset==='custom'?h('div',{class:'dates'},
      h('input',{type:'date',class:'in','aria-label':'开始日期',value:cfg.start,onchange:e=>{const v=e.target.value;saveCfg(c=>Object.assign({},c,{start:v}));}}),
      h('span',{class:'mut'},'至'),
      h('input',{type:'date',class:'in','aria-label':'结束日期',value:cfg.end,onchange:e=>{const v=e.target.value;saveCfg(c=>Object.assign({},c,{end:v}));}})
    ):null;
    const info=h('div',{class:'small '+(rangeOk(rng)?'mut':'')},rangeOk(rng)?(rng.start+' 至 '+rng.end):'⚠ 日期范围无效：请选好开始和结束日期（开始不晚于结束）');
    return h('div',{class:'rc'},chips,dates,info);
  }
  function toggleProj(id){
    saveCfg(c=>Object.assign({},c,{projects:c.projects.map(p=>p.id===id?Object.assign({},p,{on:!p.on}):p)}));
  }
  function projChips(){
    if(!cfg.projects.length)return h('div',{class:'mut small'},'还没有项目：到「设置 › 项目」添加。');
    return h('div',{class:'chips'},cfg.projects.map(p=>h('button',{type:'button',class:'chip'+(p.on?' on':''),'aria-pressed':String(!!p.on),onclick:()=>toggleProj(p.id)},(p.on?'✓ ':'')+p.name)));
  }
  function addProject(){
    const name=(ui.newProj||'').trim();
    if(!name){ui.err='请输入项目名称';redraw();return;}
    if(cfg.projects.some(p=>p.name===name)){ui.err='这个项目已经有了';redraw();return;}
    const id=uid();
    ui.newProj='';ui.err='';
    saveCfg(c=>Object.assign({},c,{projects:c.projects.concat([{id:id,name:name,on:true}])}));
  }
  function moveStep(id,dir){
    saveCfg(c=>{
      const a=c.steps.slice();
      const i=a.findIndex(x=>x.id===id),j=i+dir;
      if(i<0||j<0||j>=a.length)return c;
      const t=a[i];a[i]=a[j];a[j]=t;
      return Object.assign({},c,{steps:a});
    });
  }
  function saveStep(){
    const e0=ui.edit;
    const title=(e0.title||'').trim();
    if(!title){ui.err='请填写步骤名称';redraw();return;}
    const item={id:e0.id||uid(),title:title,kind:e0.kind,req:(e0.req||'').trim(),on:true};
    commit(s=>{
      const n=norm(s);
      const has=n.cfg.steps.some(x=>x.id===item.id);
      const steps=has?n.cfg.steps.map(x=>x.id===item.id?Object.assign({},x,{title:item.title,kind:item.kind,req:item.req}):x):n.cfg.steps.concat([item]);
      return Object.assign({},n,{cfg:Object.assign({},n.cfg,{steps:steps})});
    },Object.assign({},ui,{view:'cfg',tab:'steps',edit:null,err:''})).catch(fail);
  }

  function startRun(){
    const r=rangeOf(cfg,day());
    const steps=cfg.steps.filter(s=>s.on);
    if(!rangeOk(r)){ui.err='日期范围无效，请先到「设置 › 范围」选好';redraw();return;}
    if(!steps.length){ui.err='没有启用的步骤，请先到「设置 › 步骤」启用';redraw();return;}
    const run={
      id:uid(),at:Date.now(),start:r.start,end:r.end,
      projects:cfg.projects.filter(p=>p.on).map(p=>({id:p.id,name:p.name})),
      reportReq:cfg.reportReq||'',
      steps:steps.map((s,i)=>({id:s.id,title:s.title,req:s.req||'',kind:s.kind,status:i===0?'doing':'todo',note:''})),
      pn:{},idx:0,phase:'steps',draft:''
    };
    commit(s=>{
      const n=norm(s);
      const runs=n.runs.map(x=>(x.phase==='steps'||x.phase==='review')?Object.assign({},x,{phase:'cancelled'}):x);
      return Object.assign({},n,{runs:[run].concat(runs)});
    },Object.assign({},ui,{view:'run',runId:run.id,d:{},err:'',cf:null})).catch(fail);
  }
  const openRun=id=>nav('run',{runId:id});
  function patchRun(id,fn,nextUi){
    return commit(s=>{
      const n=norm(s);
      return Object.assign({},n,{runs:n.runs.map(r=>r.id===id?fn(r):r)});
    },nextUi||Object.assign({},ui,{d:{},err:''})).catch(fail);
