      ),
      errBar(),
      h('div',{class:'gapnote one'},'仅供查看，不会自动发送'),
      h('textarea',{class:'ta rpt','aria-label':'周报草稿',value:text,oninput:e=>{ui.d.draft=e.target.value;}}),
      h('div',{class:'btns'},acts)
    );
  }

  function histView(){
    const rows=S.runs.map(r=>h('div',{class:'row'},
      h('button',{type:'button',class:'hbtn',onclick:()=>openRun(r.id)},
        h('span',{class:'nm'},fmtTime(r.at)+' · '+md(r.start)+'–'+md(r.end)),
