    ));
    return h('div',{class:'vw'},
      h('div',{class:'hd'},btn('‹',()=>nav('home'),'sm back',false,'返回'),h('div',{class:'ttl'},'运行历史'),h('span',{class:'tag'},String(S.runs.length))),
      errBar(),
      h('div',{class:'scr'},rows.length?rows:h('div',{class:'mut small'},'还没有运行记录。'))
    );
  }

  let body;
  if(view==='cfg')body=cfgView();
  else if(view==='stepEdit')body=stepEdit();
  else if(view==='run')body=runView();
  else if(view==='hist')body=histView();
  else body=home();
  root.appendChild(h('div',{class:'wf s-'+size},body));
}

