 day(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
 async load(){const e=++this.epoch;this.stop();try{const r=await this.host.storage.get('state');if(e!==this.epoch||!this.isConnected)return;this.state=r.entry?.value||{};if(typeof initialize==='function'){const original=JSON.stringify(this.state);const prepared=initialize(JSON.parse(original));if(!prepared||typeof prepared!=='object')throw Error('initialize must return state');if(JSON.stringify(prepared)!==original){await this.host.storage.set('state',prepared);if(e!==this.epoch||!this.isConnected)return;this.state=prepared;}}this.ui={};this.saveError='';this.render();this.lastDay=this.day();this.dateTimer=setInterval(()=>{if(this.day()!==this.lastDay&&!this.pending){this.lastDay=this.day();this.render();}},1000);}catch(error){if(e===this.epoch)this.showError(error);}}
 contextShape(){const c=this.host.ctx;return JSON.stringify(Object.fromEntries(Object.entries(c).filter(([k])=>k!=='colors')));}
 updateTabbitContext(){if(!this.host)return;const shape=this.contextShape();if(shape!==this.renderedContext){this.render();return;}if(this.colorListener)this.colorListener(this.host.ctx.colors);}
